/**
 * MA-6a (DESIGN.md §8 "The phone's Apps"; VF-PM 2026-11-09 04:46Z) — ONE APP'S FACTS, generated by the Mac's own
 * reading (`made-apps.ts`). Each case is an app and the sources of its answer, in; its time, initial, standing, image
 * address, hosted host, agent label, desktop and state, out. The phone's port (the kit's `MadeAppFacts`) is held to the
 * same file, copied to `Tests/FieldHomeTests/Fixtures/made-apps/` and pinned byte for byte by `pnpm check:ios-fixtures`.
 * A change to the reading changes the golden here, and the kit's row is red until the port follows.
 *
 * The shelf's grouping (Recent, Kept, the folders) is not here: the desk groups by day, so it has no owner on this side
 * and the kit's `AppsShelfTests` are its witness. No case names an agent only by its rosetta kind: the kit's catalog
 * row carries no seam, and the door names the provider wherever a kind maps.
 *
 * `VF_WRITE_GOLDENS=1` writes the file; without it, the file must equal what the reading says now, byte for byte.
 */

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  type IndexApp,
  IndexAppsResult,
  type IndexAppsSource,
  MADE_APP_AVAILABILITIES,
} from "@vibefield/contracts";
import { describe, expect, it } from "vitest";
import {
  madeAppAgentLabel,
  madeAppAt,
  madeAppAway,
  madeAppDesktop,
  madeAppHost,
  madeAppImageUrl,
  madeAppInitial,
  madeAppSourceOf,
  madeAppStateOf,
} from "../src/frame/apps/made-apps";

const here = dirname(fileURLToPath(import.meta.url));
const GOLDENS = join(here, "fixtures/made-apps");
const WRITE = process.env.VF_WRITE_GOLDENS === "1";
const GENERATED =
  "GENERATED by packages/field-app/test/made-app-goldens.test.ts (VF_WRITE_GOLDENS=1): edit the case there, never here";
/** The word for the answering desktop when the roster names none. */
const HERE = "This desktop";

/** A golden as the generator writes it: two-space JSON and a final newline, formatted by nothing else. */
const textOf = (golden: unknown): string => `${JSON.stringify(golden, null, 2)}\n`;

/** Written under `VF_WRITE_GOLDENS=1`; else the committed file must be what the reading says now, byte for byte. */
function holds(file: string, golden: unknown): void {
  const path = join(GOLDENS, file);
  const text = textOf(golden);
  if (WRITE) {
    mkdirSync(GOLDENS, { recursive: true });
    writeFileSync(path, text);
  }
  expect(readFileSync(path, "utf8"), `${file} is not what the reading says now`).toBe(text);
}

/** One of the contracts' `index.apps.list` fixtures, parsed as the desk parses a page. */
const page = (name: string) =>
  IndexAppsResult.parse(
    JSON.parse(
      readFileSync(join(here, "../../contracts/fixtures", `index-apps.${name}.json`), "utf8"),
    ),
  );

interface Case {
  readonly name: string;
  readonly app: IndexApp;
  readonly sources: readonly IndexAppsSource[];
}

function at<T>(list: readonly T[], index: number): T {
  const value = list[index];
  if (value === undefined) throw new Error(`no entry ${index}`);
  return value;
}

function cases(): Case[] {
  const valid = page("valid");
  const mesh = page("mesh");
  const tailnet = page("tailnet");
  const base = at(valid.rows, 0);
  const source = at(valid.sources, 0);
  const onBase = (name: string, change: Partial<IndexApp>): Case => ({
    name,
    app: { ...base, ...change },
    sources: valid.sources,
  });
  const standing = (name: string, change: Partial<IndexAppsSource>): Case => ({
    name,
    app: base,
    sources: [{ ...source, ...change }],
  });
  return [
    { name: "one desktop, the newest", app: at(valid.rows, 0), sources: valid.sources },
    {
      name: "one desktop, no preview, no hosted link",
      app: at(valid.rows, 1),
      sources: valid.sources,
    },
    { name: "the mesh, an awake desktop's", app: at(mesh.rows, 0), sources: mesh.sources },
    { name: "the mesh, an asleep desktop's", app: at(mesh.rows, 1), sources: mesh.sources },
    { name: "the phone's page", app: at(tailnet.rows, 0), sources: tailnet.sources },
    ...MADE_APP_AVAILABILITIES.map((availability) =>
      onBase(`availability ${availability}`, { availability }),
    ),
    onBase("captured, and its desktop cannot write it out", { openable: false }),
    standing("asleep", { state: "asleep" }),
    standing("not answering", { self: false, state: "stale" }),
    standing("this desktop before its first walk", { self: true, state: "stale" }),
    standing("another build", { state: "incompatible" }),
    { name: "no source names its desktop", app: base, sources: [] },
    onBase("initial, composed", { title: "école" }),
    onBase("initial, decomposed", { title: "école" }),
    onBase("initial, a digit", { title: "3d tour" }),
    onBase("initial, past punctuation", { title: "— Notes" }),
    onBase("initial, from the file name", { title: "—", filename: "report.html" }),
    onBase("initial, none anywhere", { title: "—", filename: "—.—" }),
    onBase("hosted, not https", { hostedUrl: "http://claude.ai/x" }),
    onBase("hosted, not a link", { hostedUrl: "not a link" }),
    onBase("hosted, a host in capitals", { hostedUrl: "https://CLAUDE.ai/x" }),
    {
      name: "a preview, no base to fetch it from",
      app: base,
      sources: [{ ...source, previewsBase: undefined }],
    },
    onBase("an agent the catalog does not name", {
      provider: "not-a-catalog-row",
      kind: undefined,
    }),
    onBase("no agent named", { provider: undefined, kind: undefined }),
  ];
}

/** What the reading says of one case. */
function factsOf({ app, sources }: Case) {
  const source = madeAppSourceOf(app, sources);
  const desktop = madeAppDesktop(source, app.device, HERE);
  const state = madeAppStateOf(app, source, undefined, desktop);
  return {
    at: madeAppAt(app),
    initial: madeAppInitial(app),
    away: madeAppAway(source),
    imageUrl: madeAppImageUrl(app, sources) ?? null,
    host: madeAppHost(app.hostedUrl) ?? null,
    agentLabel: madeAppAgentLabel(app) ?? null,
    desktop,
    state: { tone: state.tone, word: state.word, opens: state.opens, why: state.why },
  };
}

describe("one app's facts (MA-6a): what the Mac's reading says, for the phone's port", () => {
  it("every case, field by field", () => {
    holds("made-app-facts.golden.json", {
      "//": GENERATED,
      here: HERE,
      cases: cases().map((each) => ({ ...each, facts: factsOf(each) })),
    });
  });
});
